import{_ as a,o,c as t,a3 as d}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Compatibilidade","description":"","frontmatter":{"title":"Compatibilidade"},"headers":[],"relativePath":"compatibilidade.md","filePath":"compatibilidade.md"}'),r={name:"compatibilidade.md"};function s(i,e,n,c,u,l){return o(),t("div",null,e[0]||(e[0]=[d('<h1 id="compatibilidade" tabindex="-1">Compatibilidade <a class="header-anchor" href="#compatibilidade" aria-label="Permalink to &quot;Compatibilidade&quot;">​</a></h1><h2 id="navegadores" tabindex="-1">Navegadores <a class="header-anchor" href="#navegadores" aria-label="Permalink to &quot;Navegadores&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Navegador</th><th>Situação</th></tr></thead><tbody><tr><td>Google Chrome</td><td>Compatível (instalação pela Chrome Web Store).</td></tr><tr><td>Microsoft Edge</td><td>Compatível (instalação pela mesma página da Chrome Web Store).</td></tr><tr><td>Outros navegadores (Firefox, Safari)</td><td>Não compatíveis.</td></tr></tbody></table><p>Mantenha o navegador atualizado. O eploc é uma extensão Manifest V3, o formato atual de extensões do Chrome e do Edge.</p><p>O backup no Google Drive funciona nos dois navegadores, porque a conexão com a conta Google é feita por uma janela de autorização própria, e não pela conta conectada ao navegador.</p><h2 id="sistemas-e-enderecos-atendidos" tabindex="-1">Sistemas e endereços atendidos <a class="header-anchor" href="#sistemas-e-enderecos-atendidos" aria-label="Permalink to &quot;Sistemas e endereços atendidos&quot;">​</a></h2><h3 id="eproc" tabindex="-1">eproc <a class="header-anchor" href="#eproc" aria-label="Permalink to &quot;eproc&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tribunal</th><th>Endereços</th></tr></thead><tbody><tr><td>TRF2</td><td><code>eproc.trf2.jus.br</code>, <code>eproc.jfrj.jus.br</code>, <code>eproc.jfes.jus.br</code></td></tr><tr><td>TRF4</td><td><code>eproc.trf4.jus.br</code>, <code>eproc.jfrs.jus.br</code>, <code>eproc.jfsc.jus.br</code>, <code>eproc.jfpr.jus.br</code></td></tr><tr><td>TRF6</td><td><code>eproc1g.trf6.jus.br</code>, <code>eproc2g.trf6.jus.br</code></td></tr><tr><td>TJRS</td><td><code>eproc1g.tjrs.jus.br</code>, <code>eproc2g.tjrs.jus.br</code></td></tr><tr><td>TJSC</td><td><code>eproc1g.tjsc.jus.br</code>, <code>eproc2g.tjsc.jus.br</code></td></tr><tr><td>TJTO</td><td><code>eproc1.tjto.jus.br</code>, <code>eproc2.tjto.jus.br</code></td></tr><tr><td>TJRJ</td><td><code>eproc1g.tjrj.jus.br</code>, <code>eproc2g.tjrj.jus.br</code></td></tr><tr><td>TJSP</td><td><code>eproc1g.tjsp.jus.br</code>, <code>eproc2g.tjsp.jus.br</code></td></tr><tr><td>TJMG</td><td><code>eproc1g.tjmg.jus.br</code>, <code>eproc2g.tjmg.jus.br</code></td></tr></tbody></table><p>Outros tribunais que adotam o eproc ainda não estão habilitados: cada novo endereço faz o navegador pedir as permissões de novo, então eles são incluídos conforme a procura. Se você usa o eproc de um tribunal que não está na lista, fale com o desenvolvedor (veja <a href="./contato">Contato</a>).</p><p>Alguns tribunais personalizam o eproc (telas, campos, nomes de rotinas). Nesses casos, uma funcionalidade do eploc pode se comportar de forma diferente da descrita neste manual. Se alguma não funcionar como esperado no seu tribunal, avise pelo <a href="./contato">Contato</a>, informando o tribunal, a tela e o que aconteceu.</p><h3 id="outros-sistemas" tabindex="-1">Outros sistemas <a class="header-anchor" href="#outros-sistemas" aria-label="Permalink to &quot;Outros sistemas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Sistema</th><th>Endereço</th><th>Funcionalidades</th></tr></thead><tbody><tr><td>SEI</td><td><code>*.jus.br/sei/</code> (tela de controle de processos)</td><td><a href="./funcionalidades/sei-mais-descritivo-horizontal">SEI mais descritivo e horizontal</a></td></tr><tr><td>RUPE (TJMG)</td><td><code>rupe.tjmg.jus.br</code></td><td><a href="./funcionalidades/rupe-cpha-preenchimento">Preenchimento automático de CPHA</a>, <a href="./funcionalidades/rupe-espelho-painel-pesquisa">Espelho dos Critérios de Pesquisa de Certidão</a></td></tr><tr><td>Consulta de advogados dativos (TJMG)</td><td><code>consulta-dativos.tjmg.jus.br</code></td><td><a href="./funcionalidades/tjmg-dativos-pesquisa-paginacao">Melhorar consulta de advogados dativos</a></td></tr><tr><td>Meu Gabinete (TJMG)</td><td><code>meugabinete.tjmg.jus.br</code> e o quadro de login <code>sso.cloud.pje.jus.br</code></td><td><a href="./funcionalidades/tjmg-meu-gabinete-altura-login">Corrigir a área visível para login no Meu Gabinete</a></td></tr><tr><td>PJe Mídias</td><td><code>midias.pje.jus.br</code> (só consulta)</td><td><a href="./funcionalidades/eproc-midias-link">Atalho PJe Mídias</a></td></tr></tbody></table><h2 id="funcionalidades-especificas-do-tjmg" tabindex="-1">Funcionalidades específicas do TJMG <a class="header-anchor" href="#funcionalidades-especificas-do-tjmg" aria-label="Permalink to &quot;Funcionalidades específicas do TJMG&quot;">​</a></h2><p>Algumas funcionalidades do eproc só fazem sentido no TJMG e trazem o selo <strong>eproc · TJMG</strong>: as de processos migrados do PJe (grupo Migração PJe) e o <a href="./funcionalidades/eproc-logo-tjmg-navbar">Símbolo do TJMG no menu superior</a>. Nos demais tribunais elas simplesmente não encontram o que procuram e não alteram nada.</p><h2 id="quando-o-sistema-muda" tabindex="-1">Quando o sistema muda <a class="header-anchor" href="#quando-o-sistema-muda" aria-label="Permalink to &quot;Quando o sistema muda&quot;">​</a></h2><p>O eproc, o SEI e o RUPE são atualizados pelos tribunais sem aviso. Uma mudança de tela pode fazer uma funcionalidade deixar de funcionar até o eploc ser ajustado. Nesse caso, desligue a funcionalidade no <a href="./geral/popup">popup</a> e avise pelo <a href="./contato">Contato</a>.</p><p>Antes de abrir um chamado no suporte do tribunal sobre uma falha no sistema, desative o eploc e tente de novo. Veja <a href="./perguntas-frequentes#o-sistema-do-tribunal-apresentou-um-erro-devo-abrir-um-chamado">O sistema do tribunal apresentou um erro</a>.</p>',17)]))}const b=a(r,[["render",s]]);export{m as __pageData,b as default};
